SELECT tablespace_name, status, contents FROM dba_tablespaces;

CREATE TABLE "SITRA_ORO"."MINEROS" 
(
  "ID_MINERO" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER NOCYCLE NOKEEP NOSCALE NOT NULL ENABLE, 
  "DOCUMENTO_IDENTIDAD" VARCHAR2(15) NOT NULL ENABLE, 
  "NOMBRES_APELLIDOS" VARCHAR2(150) NOT NULL ENABLE, 
  "TELEFONO" VARCHAR2(20), 
  "ZONA_PROCEDENCIA" VARCHAR2(100), 
  "FECHA_REGISTRO" TIMESTAMP (6) DEFAULT CURRENT_TIMESTAMP NOT NULL ENABLE, 
  "ID_CENTRO_ACOPIO" NUMBER(19,0), 

  -- Índice de Primary Key apuntando a TS_INDICES
  PRIMARY KEY ("ID_MINERO")
  USING INDEX LOCAL
  (
    PARTITION "SYS_P2446" TABLESPACE "TS_INDICES", 
    PARTITION "SYS_P2447" TABLESPACE "TS_INDICES", 
    PARTITION "SYS_P2448" TABLESPACE "TS_INDICES", 
    PARTITION "SYS_P2449" TABLESPACE "TS_INDICES"
  ) ENABLE, 

  -- Índice Unique apuntando a TS_INDICES
  UNIQUE ("DOCUMENTO_IDENTIDAD")
  USING INDEX TABLESPACE "TS_INDICES" ENABLE, 

  CONSTRAINT "FK_MINERO_CENTRO" FOREIGN KEY ("ID_CENTRO_ACOPIO")
    REFERENCES "SITRA_ORO"."CENTROS_ACOPIO" ("ID_CENTRO_ACOPIO") ENABLE
) 
TABLESPACE "TS_OPERACIONAL" 
PARTITION BY HASH ("ID_MINERO") 
(
  PARTITION "SYS_P2446" TABLESPACE "TS_OPERACIONAL", 
  PARTITION "SYS_P2447" TABLESPACE "TS_OPERACIONAL", 
  PARTITION "SYS_P2448" TABLESPACE "TS_OPERACIONAL", 
  PARTITION "SYS_P2449" TABLESPACE "TS_OPERACIONAL"
);

-- Índice foráneo apuntando a TS_INDICES
CREATE INDEX "SITRA_ORO"."IX_MINERO_CENTRO" 
ON "SITRA_ORO"."MINEROS" ("ID_CENTRO_ACOPIO") 
TABLESPACE "TS_INDICES";


-- 1. Mover particiones de datos a TS_OPERACIONAL
ALTER TABLE "SITRA_ORO"."MINEROS" MOVE PARTITION "SYS_P2446" TABLESPACE "TS_OPERACIONAL";
ALTER TABLE "SITRA_ORO"."MINEROS" MOVE PARTITION "SYS_P2447" TABLESPACE "TS_OPERACIONAL";
ALTER TABLE "SITRA_ORO"."MINEROS" MOVE PARTITION "SYS_P2448" TABLESPACE "TS_OPERACIONAL";
ALTER TABLE "SITRA_ORO"."MINEROS" MOVE PARTITION "SYS_P2449" TABLESPACE "TS_OPERACIONAL";

-- 2. Reconstruir los índices en TS_INDICES
ALTER TABLE "SITRA_ORO"."MINEROS" MODIFY PARTITION "SYS_P2446" REBUILD UNUSABLE LOCAL INDEXES;
ALTER TABLE "SITRA_ORO"."MINEROS" MODIFY PARTITION "SYS_P2447" REBUILD UNUSABLE LOCAL INDEXES;
ALTER TABLE "SITRA_ORO"."MINEROS" MODIFY PARTITION "SYS_P2448" REBUILD UNUSABLE LOCAL INDEXES;
ALTER TABLE "SITRA_ORO"."MINEROS" MODIFY PARTITION "SYS_P2449" REBUILD UNUSABLE LOCAL INDEXES;

ALTER INDEX "SITRA_ORO"."IX_MINERO_CENTRO" REBUILD TABLESPACE "TS_INDICES";
-- ============================================================================
-- S14: TABLA DE AUDITORÍA DE ACCIONES CRÍTICAS (LP2 - UNIDAD 3)
-- ============================================================================
CREATE TABLE AUDITORIA (
    ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ACTOR VARCHAR2(100),
    ACCION VARCHAR2(50) NOT NULL,
    ENTIDAD VARCHAR2(50) NOT NULL,
    ENTIDAD_ID NUMBER,
    FECHA TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
    DETALLE VARCHAR2(500)
);

GRANT SELECT, INSERT, UPDATE, DELETE ON AUDITORIA TO BOMERP_APP;
